#include "native.h"
J *get(J*j,const char*k){return cJSON_GetObjectItemCaseSensitive(j,k);} const char *str(J*j,const char*k){J*v=get(j,k);return cJSON_IsString(v)?v->valuestring:"";} double num(J*j,const char*k){return cJSON_GetNumberValue(get(j,k));} int truth(J*j,const char*k){return cJSON_IsTrue(get(j,k));}
void set(J*j,const char*k,J*v){if(!v)v=cJSON_CreateNull();if(get(j,k))cJSON_ReplaceItemInObjectCaseSensitive(j,k,v);else cJSON_AddItemToObject(j,k,v);} void ss(J*j,const char*k,const char*s){set(j,k,cJSON_CreateString(s?s:""));} void sn(J*j,const char*k,double n){set(j,k,cJSON_CreateNumber(n));} J *dup(J*j){return j?cJSON_Duplicate(j,1):cJSON_CreateNull();} char *json(J*j){return cJSON_PrintUnformatted(j);} int eq(J*a,J*b){return a&&b?cJSON_Compare(a,b,1):a==b;}
wchar_t *wide(const char*s){int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s?s:"",-1,0,0);if(!n)n=1;wchar_t*r=calloc(n,sizeof(wchar_t));if(r)MultiByteToWideChar(CP_UTF8,0,s?s:"",-1,r,n);return r;} char *utf8(const wchar_t*s){int n=WideCharToMultiByte(CP_UTF8,0,s?s:L"",-1,0,0,0,0);char*r=calloc(n?n:1,1);if(r)WideCharToMultiByte(CP_UTF8,0,s?s:L"",-1,r,n,0,0);return r;}
void uuid(char*s){GUID g;CoCreateGuid(&g);sprintf(s,"%08lx-%04x-%04x-%02x%02x-%02x%02x%02x%02x%02x%02x",g.Data1,g.Data2,g.Data3,g.Data4[0],g.Data4[1],g.Data4[2],g.Data4[3],g.Data4[4],g.Data4[5],g.Data4[6],g.Data4[7]);}
void now(char*s){SYSTEMTIME t;GetSystemTime(&t);sprintf(s,"%04d-%02d-%02dT%02d:%02d:%02d.%03dZ",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond,t.wMilliseconds);}
int64_t time_ms(const char*s){SYSTEMTIME t={0};FILETIME f;ULARGE_INTEGER n;if(!s||strlen(s)!=16||sscanf(s,"%hu-%hu-%huT%hu:%hu",&t.wYear,&t.wMonth,&t.wDay,&t.wHour,&t.wMinute)!=5||!SystemTimeToFileTime(&t,&f))return -1;n.LowPart=f.dwLowDateTime;n.HighPart=f.dwHighDateTime;int64_t v=(int64_t)(n.QuadPart/10000)-11644473600000LL-28800000;char test[32];format_ms(v,test);return strcmp(test,s)?-1:v;}
void format_ms(int64_t n,char*s){ULARGE_INTEGER u;u.QuadPart=(n+11644473600000LL+28800000)*10000;FILETIME f={u.LowPart,u.HighPart};SYSTEMTIME t;FileTimeToSystemTime(&f,&t);sprintf(s,"%04d-%02d-%02dT%02d:%02d",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute);}
void join(wchar_t*out,const wchar_t*d,const wchar_t*n){swprintf(out,32768,L"%s\\%s",d,n);} int ensure_dir(const wchar_t*p){int r=SHCreateDirectoryExW(0,p,0);return r==ERROR_SUCCESS||r==ERROR_ALREADY_EXISTS||r==ERROR_FILE_EXISTS;}
char *read_file(const wchar_t*p){FILE*f=_wfopen(p,L"rb");if(!f)return 0;_fseeki64(f,0,SEEK_END);int64_t n=_ftelli64(f);rewind(f);if(n<0||n>64*1024*1024){fclose(f);return 0;}char*s=malloc((size_t)n+1);if(!s){fclose(f);return 0;}size_t count=fread(s,1,(size_t)n,f);fclose(f);s[count]=0;return s;}
int write_file(const wchar_t*p,const char*s){wchar_t tmp[32768];swprintf(tmp,32768,L"%s.tmp-%lu",p,GetCurrentProcessId());FILE*f=_wfopen(tmp,L"wb");if(!f)return 0;int ok=fwrite(s,1,strlen(s),f)==strlen(s)&&fflush(f)==0;fclose(f);if(ok)ok=MoveFileExW(tmp,p,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(!ok)DeleteFileW(tmp);return ok;}
void sha256(const char*s,char*out){HCRYPTPROV p=0;HCRYPTHASH h=0;BYTE b[32];DWORD n=32;out[0]=0;if(CryptAcquireContextW(&p,0,0,PROV_RSA_AES,CRYPT_VERIFYCONTEXT)&&CryptCreateHash(p,CALG_SHA_256,0,0,&h)&&CryptHashData(h,(BYTE*)s,(DWORD)strlen(s),0)&&CryptGetHashParam(h,HP_HASHVAL,b,&n,0)){for(int i=0;i<32;i++)sprintf(out+i*2,"%02x",b[i]);}if(h)CryptDestroyHash(h);if(p)CryptReleaseContext(p,0);}
